"""Streamlit demo for explaining and safely testing a SQL repair."""
from pathlib import Path

import requests
import streamlit as st

from benchmark import DB_PATH, SCHEMA_TEXT, create_database
from evaluator import parse_model_json
from model_client import ModelResponseError, generate_fix
from sql_validator import execute_readonly, validate_select

st.set_page_config(page_title="SQL Error Explainer & Fixer", page_icon="🛠️")
st.title("SQL Error Explainer & Fixer")
st.caption("Gemma 3 4B · LM Studio local inference · SQLite sandbox")
st.info(
    "Repairs are generated by your local model. Proposed queries are validated "
    "and run only against the synthetic sample database."
)

database_path = str(Path(__file__).resolve().with_name(DB_PATH))
if not Path(database_path).exists():
    create_database(database_path)

schema = st.text_area("Database schema", SCHEMA_TEXT, height=110)
sql = st.text_area("SQL query to explain or fix", "SELEC name, age FROM Students;", height=120)
if st.button("Explain and fix SQL", type="primary"):
    st.session_state.pop("repair", None)
    st.session_state.pop("execution", None)
    if not sql.strip():
        st.error("Enter a SQL query first.")
    elif not schema.strip():
        st.error("Provide the database schema first.")
    else:
        with st.spinner("Asking local Gemma model..."):
            try:
                response = generate_fix(sql, schema)
                st.session_state["repair"] = {
                    "response": response,
                    "parsed": parse_model_json(response["raw_response"]),
                }
            except requests.RequestException as exc:
                st.error(f"Could not contact the local model server: {exc}")
                st.caption(
                    "Check that LM Studio's local server is running and the configured model is loaded."
                )
            except (ModelResponseError, ValueError) as exc:
                st.error(str(exc))

repair = st.session_state.get("repair")
if repair:
    response = repair["response"]
    parsed = repair["parsed"]
    st.subheader("Explanation")
    st.write(parsed.get("explanation") or "No explanation returned.")
    st.subheader("Proposed SQL")
    fixed = parsed.get("fixed_sql", "")
    st.code(fixed or "(No safe correction returned)", language="sql")
    st.write("Error type:", parsed.get("error_type", "unknown"))
    st.write("Assumptions:", parsed.get("assumptions") or "None")
    st.write(f"Model response time: {response['latency_seconds']} seconds")
    if parsed.get("_parse_error"):
        st.warning(
            "The model response was not valid structured JSON. Review it before using any suggestion."
        )

    allowed, cleaned, reason = validate_select(fixed)
    st.write("Safety validation:", "PASS" if allowed else "BLOCKED")
    st.caption(reason)
    if allowed and st.button("Execute safe fix against sample database", key="execute_fix"):
        st.session_state["execution"] = execute_readonly(database_path, cleaned)

    execution = st.session_state.get("execution")
    if execution:
        if execution["ok"]:
            st.success("Executed successfully")
            st.dataframe(execution["rows"], use_container_width=True)
            st.write("Columns:", execution["columns"])
        else:
            st.error(execution["reason"])

    with st.expander("Raw model response"):
        st.code(response["raw_response"])
